const deletion = document.createElement('button'); deletion.type = 'button'; deletion.textContent = task.deleted ? 'Restore task' : 'Delete task'; deletion.disabled = Boolean(project.archived);
deletion.addEventListener('click', async () => {
  const response = await fetch(`/api/projects/${project.id}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ deleted: !Boolean(task.deleted) }) });
  if (!response.ok) { alert.textContent = 'Unable to update task'; return; }
  alert.textContent = ''; await renderTasks();
});
label.append(checkbox); row.append(title, renameInput, renameButton, priorityLabel, priority, dueDateInput, saveDueDate, notes, saveNotes, destination, moveButton, deletion, label); list.append(row);

